// Start of the rolling window, measured in Baghdad terms so the boundary does
// not drift a day when the job runs at 02:00 local.
const days = Number($('Config').first().json.windowDays) || 35;
const d = new Date(Date.now() - days * 86400000);
const from = d.toLocaleDateString('en-CA', { timeZone: 'Asia/Baghdad' });
return [{ json: { from } }];

// account.invoice.report -> dashboard_invoice_lines.
// Odoo many2one fields arrive as [id, "Label"]. Credit notes (out_refund) come
// through with NEGATIVE quantity and price_subtotal - verified 2026-08-01 - so
// they are stored as-is and every sum nets returns automatically. Never abs().
const id0  = v => Array.isArray(v) ? v[0] : ((v === false || v == null) ? null : v);
const lbl  = v => Array.isArray(v) ? v[1] : ((v === false || v == null) ? null : v);
const num  = v => (v === false || v == null) ? 0 : Number(v);
const nnum = v => (v === false || v == null) ? null : Number(v);

const byId = new Map();                       // de-dupe: the source can emit repeats
for (const r of $input.all().map(i => i.json)) {
  if (!r || r.id == null) continue;           // also skips the empty item that
  const pid = id0(r.product_id);              // alwaysOutputData emits for a
  if (!pid || !r.invoice_date) continue;      // month with no invoices
  byId.set(r.id, {
    line_id:          r.id,
    move_id:          id0(r.move_id),
    product_id:       pid,
    qty:              num(r.quantity),
    price_subtotal:   num(r.price_subtotal),
    price_total:      nnum(r.price_total),
    price_margin:     nnum(r.price_margin),
    inventory_value:  nnum(r.inventory_value),
    invoice_date:     String(r.invoice_date).slice(0, 10),
    partner_id:       id0(r.commercial_partner_id) ?? id0(r.partner_id),
    salesperson:      lbl(r.invoice_user_id),
    user_id:          id0(r.invoice_user_id),
    move_type:        r.move_type,
    state:            r.state,
    payment_state:    r.payment_state || null,
    product_categ_id: id0(r.product_categ_id),
    category:         lbl(r.product_categ_id),
    product_brand_id: id0(r.product_brand_id),
    brand:            lbl(r.product_brand_id),
    state_id:         id0(r.state_id),
    gov:              lbl(r.state_id),
    city_id:          id0(r.city_id),
    city:             lbl(r.city_id),
    team_id:          id0(r.team_id)
  });
}
return [{ json: { rows: [...byId.values()], count: byId.size } }];

// Runs AFTER the delete, re-reading the rows Map Rows already fetched.
const rows = $('Map Rows').first().json.rows || [];
const CH = 500, items = [];
for (let i = 0; i < rows.length; i += CH) items.push({ json: { rows: rows.slice(i, i + CH) } });
return items.length ? items : [{ json: { rows: [] } }];
